sys_script_fix.script:
(function() {

    var gr = new GlideRecord('x_1303852_drama_drama');
    gr.addNotNullQuery('url');
    gr.query();

    while (gr.next()) {

        try {
            var url = gr.getValue('url');

            var rm = new sn_ws.RESTMessageV2();
            rm.setHttpMethod('GET');
            rm.setEndpoint(url);

            var response = rm.execute();

            if (response.getStatusCode() != 200) {
                gs.error('Failed to fetch URL: ' + url +
                    ' Status: ' + response.getStatusCode());
                continue;
            }

            var html = response.getBody();

            var rating = extractRating(html);
            if (rating) {
                gr.setValue('viewer_rating', rating);
				gr.update();
                gs.info('Updated rating for ' +
                    gr.getDisplayValue() +
                    ' -> ' + rating);
            }

        } catch (ex) {

            gs.error('Error processing ' +
                gr.getValue('url') +
                ': ' + ex);

        }

    }

    function extractRating(html) {

        var scriptRegex = /<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/i;
        var scriptMatch = html.match(scriptRegex);

        if (!scriptMatch) {
            return null;
        }

        try {

            var data = JSON.parse(scriptMatch[1]);
            if (
                data.aggregateRating &&
                data.aggregateRating.ratingValue
            ) {
                return parseFloat(data.aggregateRating.ratingValue);
            }

        } catch (e) {
            gs.error('JSON parse failed: ' + e);
        }

        return null;
    }

})();
